export const messages = { zh, en, th, ar } as const;
export type MessageTree = typeof zh;
export type Translator = (key: string, vars?: Record<string, string | number>) => string;

function lookup(tree: unknown, key: string): unknown {
  return key.split('.').reduce<unknown>((current, part) => {
    if (current && typeof current === 'object' && part in (current as Record<string, unknown>)) {
      return (current as Record<string, unknown>)[part];
    }
    return undefined;
  }, tree);
}

export function translate(locale: Locale, key: string, vars?: Record<string, string | number>): string {
  const value = lookup(messages[locale], key) ?? lookup(messages.zh, key) ?? key;
  return String(value).replace(/\{(\w+)\}/g, (_, name: string) => String(vars?.[name] ?? `{${name}}`));
}

export function getDictionary(locale: Locale = 'zh') {
  return messages[locale] ?? messages.zh;
}

export function createTranslator(locale: Locale): Translator {
  return (key, vars) => translate(locale, key, vars);
}

export function getDir(locale: Locale = 'zh'): 'ltr' | 'rtl' {
  return LOCALES.find((item) => item.code === locale)?.dir ?? 'ltr';
}

export function getIntlLocale(locale: Locale = 'zh'): string {
  return locale === 'zh' ? 'zh-CN' : locale === 'th' ? 'th-TH' : locale === 'ar' ? 'ar-AE' : 'en-US';
}
